import React, { useState, useRef, useEffect } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import ProfModal from './ProfModal';

export default function Chatbot() {
  const { user } = useAuth();
  const [messages, setMessages] = useState([
    {
      id: 1, role: 'bot',
      text: `Bonjour **${user?.nom?.split(' ')[0] || ''}** ! 👋 Je suis **EduBot**, votre assistant IA.\n\nDites-moi ce que vous cherchez !\n*Exemple : « Je cherche un prof de maths pas cher à Sfax »*`,
      time: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedProf, setSelectedProf] = useState(null);
  const bottomRef = useRef(null);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages]);

  function addMsg(role, text, extra = {}) {
    setMessages(prev => [...prev, { id: Date.now(), role, text, ...extra, time: new Date() }]);
  }

  async function sendMessage() {
    if (!input.trim() || loading) return;
    const msg = input.trim();
    setInput('');
    addMsg('user', msg);
    setLoading(true);

    const history = messages.slice(-10).map(m => ({ role: m.role === 'bot' ? 'assistant' : 'user', content: m.text }));

    try {
      const { data } = await api.post('/api/chatbot/message', { message: msg, history });
      addMsg('bot', data.reply, { results: data.matched_profs || null });
    } catch (e) {
      addMsg('bot', 'Désolé, une erreur est survenue. Veuillez réessayer. 🙏');
    }
    setLoading(false);
  }

  function handleKey(e) { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } }

  function fmt(text) {
    return text
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/g, '<em>$1</em>')
      .replace(/\n/g, '<br/>');
  }

  return (
    <div style={{ padding: 32 }}>
      <div style={{ marginBottom: 20 }}>
        <div style={{ fontFamily: 'Syne', fontSize: '1.2rem', fontWeight: 700 }}>🤖 Assistant IA EduBot</div>
        <div style={{ fontSize: '.85rem', color: 'var(--text2)' }}>Décrivez vos besoins, je trouve le prof parfait pour vous</div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 200px)', background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, overflow: 'hidden' }}>
        {/* Header */}
        <div style={{ padding: '20px 24px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 14, background: 'linear-gradient(135deg,rgba(108,99,255,.1),rgba(255,101,132,.05))' }}>
          <div style={{ width: 44, height: 44, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.3rem' }}>🤖</div>
          <div>
            <div style={{ fontFamily: 'Syne', fontWeight: 700 }}>EduBot</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.78rem', color: '#43e97b' }}>
              <div style={{ width: 8, height: 8, background: '#43e97b', borderRadius: '50%', animation: 'pulse 1.5s infinite' }} />
              En ligne – Matching IA actif
            </div>
          </div>
        </div>

        {/* Messages */}
        <div style={{ flex: 1, overflowY: 'auto', padding: 20, display: 'flex', flexDirection: 'column', gap: 14 }}>
          {messages.map(m => (
            <div key={m.id} style={{ display: 'flex', gap: 10, maxWidth: '80%', ...(m.role === 'user' ? { flexDirection: 'row-reverse', alignSelf: 'flex-end' } : {}) }}>
              <div style={{ width: 32, height: 32, borderRadius: '50%', background: m.role === 'bot' ? 'linear-gradient(135deg,#6c63ff,#ff6584)' : 'linear-gradient(135deg,#f59e0b,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', flexShrink: 0 }}>
                {m.role === 'bot' ? '🤖' : '👤'}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <div style={{ padding: '12px 16px', borderRadius: 14, fontSize: '.88rem', lineHeight: 1.55, ...(m.role === 'bot' ? { background: 'var(--surface2)', border: '1px solid var(--border)', borderTopLeftRadius: 4 } : { background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', borderTopRightRadius: 4 }) }}
                  dangerouslySetInnerHTML={{ __html: fmt(m.text) }}
                />
                {/* Matched profs */}
                {m.results && (
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {m.results.map(p => (
                      <div key={p.id} onClick={() => setSelectedProf(p)} style={{ background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 10, padding: 14, cursor: 'pointer', transition: '.2s' }}
                        onMouseEnter={e => e.currentTarget.style.borderColor = '#6c63ff'}
                        onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
                      >
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
                          <div style={{ fontSize: '1.4rem' }}>👨‍🏫</div>
                          <div>
                            <div style={{ fontWeight: 600, fontSize: '.85rem' }}>{p.user_nom || p.nom}</div>
                            <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{p.matiere}</div>
                          </div>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', background: 'rgba(108,99,255,.1)', border: '1px solid rgba(108,99,255,.2)', borderRadius: 8, marginBottom: 8 }}>
                          <span style={{ fontSize: '.7rem', color: 'var(--text2)' }}>Match</span>
                          <div style={{ flex: 1, height: 5, background: 'var(--surface2)', borderRadius: 3, overflow: 'hidden' }}>
                            <div style={{ height: '100%', background: 'linear-gradient(90deg,#6c63ff,#43e97b)', borderRadius: 3, width: `${p.score}%` }} />
                          </div>
                          <span style={{ fontSize: '.78rem', fontWeight: 700, color: '#6c63ff' }}>{p.score}%</span>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <span style={{ color: '#f59e0b', fontSize: '.82rem' }}>{'★'.repeat(Math.floor(p.note || 0))} {parseFloat(p.note || 0).toFixed(1)}</span>
                          <span style={{ fontSize: '.78rem', fontWeight: 600, color: '#43e97b' }}>{p.tarif} DT/h</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
                <div style={{ fontSize: '.7rem', color: 'var(--text2)' }}>{m.time?.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}</div>
              </div>
            </div>
          ))}

          {loading && (
            <div style={{ display: 'flex', gap: 10 }}>
              <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>🤖</div>
              <div style={{ padding: '12px 16px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 14, borderTopLeftRadius: 4 }}>
                <div style={{ display: 'flex', gap: 4 }}>
                  {[0, 1, 2].map(i => <div key={i} style={{ width: 7, height: 7, background: 'var(--text2)', borderRadius: '50%', animation: `typing 1.2s ${i * 0.2}s infinite` }} />)}
                </div>
              </div>
            </div>
          )}
          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div style={{ padding: '16px 20px', borderTop: '1px solid var(--border)', display: 'flex', gap: 12, alignItems: 'flex-end' }}>
          <textarea
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={handleKey}
            placeholder="Ex: Je cherche un prof de maths pour la terminale à Sfax..."
            rows={1}
            style={{ flex: 1, background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 12, padding: '12px 16px', color: 'var(--text)', fontSize: '.9rem', resize: 'none', outline: 'none', fontFamily: 'DM Sans, sans-serif' }}
          />
          <button
            onClick={sendMessage}
            disabled={loading || !input.trim()}
            style={{ width: 44, height: 44, borderRadius: 12, background: loading || !input.trim() ? 'var(--surface2)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', cursor: loading || !input.trim() ? 'not-allowed' : 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}
          >➤</button>
        </div>
      </div>

      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}

      <style>{`
        @keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}
        @keyframes typing{0%,80%,100%{transform:scale(1);opacity:.5}40%{transform:scale(1.3);opacity:1}}
      `}</style>
    </div>
  );
}
